SELECT d.author_key AS author_key,d.doc_id AS doc_id,toUnixTimestamp64Milli(d.created_at) AS created_ms,g.group_id AS group_id FROM (SELECT author_key,doc_id,created_at,deleted,row_number() OVER (PARTITION BY author_key,doc_id ORDER BY updated_at DESC,deleted DESC) AS rn FROM documents WHERE author_key IN (unhex('61'),unhex('62'))) AS d INNER JOIN (SELECT doc_id,group_id,deleted,row_number() OVER (PARTITION BY doc_id,group_id ORDER BY updated_at DESC,deleted DESC) AS rn FROM doc_groups WHERE group_id IN (unhex('6731'),unhex('6732')) AND doc_id IN (SELECT doc_id FROM documents WHERE author_key IN (unhex('61'),unhex('62')))) AS g ON d.doc_id=g.doc_id WHERE d.rn=1 AND d.deleted=0 AND g.rn=1 AND g.deleted=0
